app.addEventListener('input',e=>{const el=e.target;if(el.dataset.basic&&draft)draft[el.dataset.basic]=el.value;if(el.dataset.total&&draft){draft.totals[el.dataset.total]=el.value===''?null:Number(el.value);updateChecks();}const row=el.closest('[data-item]');if(row&&draft&&el.dataset.itemkey){const i=draft.items.find(i=>i.id===row.dataset.item),k=el.dataset.itemkey;i[k]=['value','cumulative','paidHours'].includes(k)?el.value===''?null:Number(el.value):el.value;if(k==='value')i.state=i.value===null?'unknown':'value';if(k==='state'){if(i.state==='unprovided')i.value=null;row.querySelector('[data-itemkey=value]').disabled=i.state==='unprovided';row.querySelector('[data-itemkey=value]').value=i.value??'';}row.querySelector('[data-itemkey=state]').value=i.state;updateChecks();}if(ocrSession)queueOcrCheckpoint();});
