if(a==='add-item'){const g=btn.dataset.group;if(await ask('新增自訂項目','<label>項目名稱<input id="newItemName" maxlength="80"></label>')){const name=$('#newItemName').value.trim();if(!name)throw Error('名稱不可空白');if(draft.items.some(i=>i.group===g&&i.name===name))throw Error('此分類已有同名項目');draft.items.push({id:uid(),group:g,name,value:null,state:'unknown',tax:'unknown',unit:g==='attendance'?'小時':'元',cumulative:null,paidHours:null,sourcePage:null,ocrValue:null,confidence:null});document.querySelector(`[data-group="${g}"]`).insertAdjacentHTML('beforeend',itemRow(draft.items.at(-1)));updateChecks();}}
