window.addEventListener('hashchange',()=>{if(busy)return;render().catch(e=>toast(e.message));});window.addEventListener('beforeunload',e=>{if(draft||busy){e.preventDefault();e.returnValue='';}});window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;installOutcome='';if(view==='install')render();});window.addEventListener('appinstalled',()=>{installOutcome='installed';updateOfflineStatus();if(view==='install')render();});
